from __future__ import absolute_import
import logging
from collections import defaultdict
from selenium.common.exceptions import TimeoutException
from taf.selenium.gnb.oam.coam.classical.pages.panels.navigation import NavigationPanel
from taf.selenium.gnb.oam.coam.classical.pages.panels.view import ViewPanel
from taf.selenium.gnb.oam.coam.classical.pages.panels.details import DetailPanel
from taf.selenium.gnb.oam.coam.classical.pages.navigatable_page import NavigatablePage


class RelationErrorsPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Relation Errors will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Relation Errors']

    def __init__(self, driver):
        super(RelationErrorsPage, self).__init__(driver)
        self._view_panel = RelationErrorsPageViewPanel(driver)

    def get_relation_errors(self, timeout):
        return self._view_panel.get_relation_errors(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class RelationErrorsPageNavigationPanel(NavigationPanel):
    pass


class RelationErrorsPageViewPanel(ViewPanel):
    _ERROR_TABLE_ROWS_XPATH = '//parameter-validation-errors//tbody/tr'
    _OBJECT_NAME_XPATH = '/td[contains(@class,"object-name")]//highlighter/span'
    _ERROR_DESCRIPTION_XPATH = '//pdl-feedback/span'

    def __init__(self, driver):
        super(RelationErrorsPageViewPanel, self).__init__(driver)

    def get_relation_errors(self, timeout):
        try:
            relation_errors = defaultdict(list)
            error_row_xpath_list = self.get_elements_xpath_list(self._ERROR_TABLE_ROWS_XPATH, timeout)
            for error_row_xpath in error_row_xpath_list:
                error_row_key = self._get_object_name(error_row_xpath, timeout)
                error_row_value = self._get_error_description(error_row_xpath, timeout)
                relation_errors[error_row_key].append(error_row_value)
            return relation_errors
        except TimeoutException:
            logging.warning('No relation errors exist, empty dict will be returned.')
            return dict()

    def _get_object_name(self, row_base_xpath, timeout):
        row_object_name_xpath = row_base_xpath + self._OBJECT_NAME_XPATH
        return self.get_text_by_xpath(row_object_name_xpath, timeout)

    def _get_error_description(self, row_base_xpath, timeout):
        row_error_description = ''
        row_error_description_base_xpath = row_base_xpath + self._ERROR_DESCRIPTION_XPATH
        row_error_description_xpath_list = self.get_elements_xpath_list(row_error_description_base_xpath, timeout)

        for xpath in row_error_description_xpath_list:
            row_error_description = ' '.join([row_error_description, self.get_text_by_xpath(xpath, timeout)])
        return row_error_description.strip()


class RelationErrorsPageDetailPanel(DetailPanel):
    pass
